use crate::aap::caps::inference_llm;
use crate::aap::caps::types::Intent;

struct Node;

/// Maximum length permitted for the input text by the node's `requires` clause.
const MAX_INPUT_LEN: usize = 4000;

/// Upper bound on the emitted `question`, from the node's `ensures` clause.
const MAX_QUESTION_LEN: usize = 512;

/// Truncate `s` to at most `max` bytes without splitting a UTF-8 code point.
fn truncate_chars(s: &str, max: usize) -> String {
    if s.len() <= max {
        return s.to_string();
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s[..end].to_string()
}

/// Map the model's free-text label onto the closed `Intent` set. The enum has no
/// "other" case, so any unrecognised label collapses to `Unknown`: adversarial
/// text cannot widen the intent set, and the `ensures` on `intent` holds by
/// construction of the return type.
fn classify_intent(label: &str) -> Intent {
    let norm: String = label
        .trim()
        .to_ascii_lowercase()
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { ' ' })
        .collect();
    let norm = norm.trim();

    match norm {
        "billing question" | "billing" | "billing_question" => Intent::BillingQuestion,
        "technical support" | "technical" | "support" | "technical_support" => {
            Intent::TechnicalSupport
        }
        "account change" | "account" | "account_change" => Intent::AccountChange,
        "general inquiry" | "general" | "inquiry" | "general_inquiry" => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // The `requires len(value.text) <= 4000` is guaranteed by the caller.
        // We defensively bound the text we hand to the model so a contract
        // violation upstream cannot turn into an unbounded prompt here.
        let text = truncate_chars(&message.text, MAX_INPUT_LEN);

        // Discharge trust by asking the inference-only model to classify the
        // message. This handle offers exactly one function and returns a string:
        // there is no tool-call to receive, so the node can be influenced by the
        // model but cannot act on its behalf.
        let system = "You are an intent classifier for a customer-support system. \
             Read the customer message and reply with EXACTLY ONE of these labels \
             and nothing else: billing_question, technical_support, account_change, \
             general_inquiry, unknown.";

        let label = inference_llm::infer(system, &text, "classify");
        let intent = classify_intent(&label);

        // The emitted question is the (bounded) customer text. `ensures
        // len(question) <= 512` is enforced here by truncation on a char
        // boundary; the result type's enum enforces the `intent` ensures.
        let question = truncate_chars(&text, MAX_QUESTION_LEN);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
```

